add_filter( 'woocommerce_package_rates', 'perfectpixel_weight_based_shipping', 10, 2 );

function perfectpixel_weight_based_shipping( $rates, $package ) {
	$weight = 0;
	foreach ( $package['contents'] as $item ) {
		$weight += (float) $item['data']->get_weight() * $item['quantity'];
	}
	$heavy = $weight > (float) '{{weight_limit}}';
	$hide  = $heavy ? '{{light_rate_ids}}' : '{{heavy_rate_ids}}';
	foreach ( array_filter( array_map( 'trim', explode( ',', $hide ) ) ) as $rate_id ) {
		unset( $rates[ $rate_id ] );
	}
	return $rates;
}
